<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
require __DIR__.'/migration-sequence.php';
use Kios\Infrastructure\{Database,StaffAccountService};
use Kios\MerchantOperations\{Inventory,StaffSessionIdentity};
$db=Database::connect();$meta=json_decode(file_get_contents($argv[1]),true);$creds=json_decode(file_get_contents($argv[2]),true);$r=['passed'=>0,'failed'=>0,'cases'=>[]];
function check(bool $v):void{if(!$v)throw new RuntimeException('Assertion failed');}
function test(string $name,callable $f):void{global $r;try{$f();$r['passed']++;$r['cases'][$name]='PASS';}catch(Throwable $e){$r['failed']++;$r['cases'][$name]=get_class($e).':'.$e->getMessage();}}
function denied(callable $f):void{try{$f();}catch(DomainException|InvalidArgumentException){return;}throw new RuntimeException('Expected denial');}
function req():string{return bin2hex(random_bytes(16));}
$svc=[];foreach(['a','b']as $w){$m=$meta['merchants'][$w];$q=$db->prepare('SELECT outlet_code FROM outlets WHERE outlet_id=?');$q->execute([$m['loginOutlet']]);$auth=new StaffAccountService($db,$q->fetchColumn(),getenv('KIOS_MERCHANT_AUTH_RATE_KEY'));$native=$auth->authenticate($m['username'],$creds['owner_'.$w.'_password'],'synthetic');check($native!==null);$session=[];StaffAccountService::bind($session,$native);$session['_merchant_login_outlet']=$m['loginOutlet'];$svc[$w]=new Inventory($db,new StaffSessionIdentity($db,static fn()=>$session,getenv('KIOS_MERCHANT_AUTH_RATE_KEY')));}
$a=$meta['merchants']['a'];$b=$meta['merchants']['b'];$call=fn($op,$d,$request=null)=>$svc['a']->act($a['merchant'],$a['outlet'],$request??req(),$op,$d);$load=fn()=>$svc['a']->load($a['merchant'],$a['outlet']);$milk=null;$sugar=null;$recipe=null;$receipt=null;
test('Migration 024 and replay',function()use($db){check(qualifiedMigrationSequence($db));check((new Kios\Infrastructure\MigrationRunner($db))->apply(dirname(__DIR__,2).'/database/migrations')===[]);});
test('Fixed precision rejects malformed quantities',function(){foreach(['-1','1e3','0.0001','01',INF]as $v)denied(fn()=>Inventory::quantity($v));check(Inventory::quantity('100.125')===100125);});
test('Create opening stock with actor attributed immutable ledger',function()use($call,$load,$db,&$milk,&$sugar){$milk=$call('ingredient',['name'=>'Milk','unit'=>'ml','opening'=>'1000','minimum'=>'200','location'=>'Chiller','supplier'=>'Synthetic dairy'])['result']['item'];$sugar=$call('ingredient',['name'=>'Sugar','unit'=>'g','opening'=>'100','minimum'=>'20','location'=>'Dry store','supplier'=>'Synthetic supply'])['result']['item'];check(count($load()['items'])===2);check((int)$db->query('SELECT COUNT(*) FROM merchant_inventory_movements')->fetchColumn()===2);});
test('Receipt exact retry and conflicting reuse',function()use($call,$load,&$receipt,$milk){$receipt=req();$d=['item'=>$milk,'quantity'=>'100','reason'=>'Synthetic receipt'];$first=$call('receipt',$d,$receipt);check($call('receipt',$d,$receipt)['duplicate']);$d['quantity']='101';denied(fn()=>$call('receipt',$d,$receipt));check($first['result']['balances_milli'][$milk]===1100000);});
test('Two merchants and cross-outlet direct ingredient references denied',function()use($svc,$a,$b,$call,$milk){denied(fn()=>$svc['a']->load($b['merchant'],$b['outlet']));denied(fn()=>$svc['a']->load($a['merchant'],$b['outlet']));denied(fn()=>$svc['b']->act($b['merchant'],$b['outlet'],req(),'receipt',['item'=>$milk,'quantity'=>'1','reason'=>'forbidden']));check($svc['b']->load($b['merchant'],$b['outlet'])['items']===[]);});
test('Recipe compatible units and own product requirement',function()use($call,$a,$b,$milk,$sugar,&$recipe){$d=['product'=>(string)$a['product'],'lines'=>[['item'=>$milk,'quantity'=>'100','unit'=>'ml'],['item'=>$sugar,'quantity'=>'10','unit'=>'g']]];$recipe=$call('recipe',$d)['result']['recipe'];$d['lines'][0]['unit']='g';denied(fn()=>$call('recipe',$d));$d['product']=(string)$b['product'];denied(fn()=>$call('recipe',$d));});
test('Recipe consumption atomically reduces multiple ingredients and alerts',function()use($call,$load,$recipe,$sugar){$result=$call('consume',['recipe'=>$recipe,'servings'=>'9','reason'=>'Synthetic tea preparation']);check($result['result']['balances_milli'][$sugar]===10000);$item=array_values(array_filter($load()['items'],fn($i)=>$i['item_id']===$sugar))[0];check($item['stock_state']==='Low stock');});
test('Insufficient stock rolls back all ingredient changes and audit',function()use($call,$load,$recipe){$before=$load();denied(fn()=>$call('consume',['recipe'=>$recipe,'servings'=>'9','reason'=>'Too much']));check($load()===$before);});
test('Reversal appends compensation and prevents duplicate reversal',function()use($call,$receipt,$load,$db){$before=(int)$db->query('SELECT COUNT(*) FROM merchant_inventory_movements')->fetchColumn();$call('reverse',['original'=>$receipt,'reason'=>'Synthetic correction']);check((int)$db->query('SELECT COUNT(*) FROM merchant_inventory_movements')->fetchColumn()===$before+1);denied(fn()=>$call('reverse',['original'=>$receipt,'reason'=>'Duplicate reversal']));});
test('Wastage adjustment and stale metadata update checks',function()use($call,$load,$sugar){$call('wastage',['item'=>$sugar,'quantity'=>'1','reason'=>'Spillage']);$call('adjustment',['item'=>$sugar,'quantity'=>'2','reason'=>'Count correction','direction'=>'increase']);$i=array_values(array_filter($load()['items'],fn($i)=>$i['item_id']===$sugar))[0];$d=['item'=>$sugar,'version'=>(string)$i['version'],'name'=>'Sugar','minimum'=>'21','location'=>'Dry store','supplier'=>'Synthetic'];$call('update',$d);denied(fn()=>$call('update',$d));});
test('Database rejects historical event movement and recipe rewrites',function()use($db){foreach(['merchant_inventory_events','merchant_inventory_movements','merchant_inventory_recipes']as $table){$failed=false;try{$db->exec('DELETE FROM '.$table);}catch(PDOException){$failed=true;}check($failed);}});
test('Audit failure rolls back balance changes',function()use($db,$call,$milk,$load){$db->exec("CREATE TRIGGER m05a_test_audit_failure BEFORE INSERT ON merchant_inventory_events FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic failure'");$before=$load();try{$failed=false;try{$call('receipt',['item'=>$milk,'quantity'=>'1','reason'=>'Audit rollback']);}catch(PDOException){$failed=true;}check($failed&&$load()===$before);}finally{$db->exec('DROP TRIGGER m05a_test_audit_failure');}});
test('Anonymous and non-owner principals denied',function()use($db,$a){foreach([null,$a['staff']['userId']] as $user){$principal=new class($user) implements \Kios\MerchantFoundation\AuthenticatedUserProvider{public function __construct(private ?string $id){}public function currentUserId():?string{return $this->id;}};denied(fn()=>(new Inventory($db,$principal))->load($a['merchant'],$a['outlet']));}});
test('UTC epochs and zero commercial activity',function()use($db){$now=(int)$db->query('SELECT MAX(occurred_epoch) FROM merchant_inventory_events')->fetchColumn();check(abs(time()-$now)<60);foreach(['orders','payment_confirmations','print_jobs']as $t)check((int)$db->query('SELECT COUNT(*) FROM '.$t)->fetchColumn()===0);});
file_put_contents($argv[3],json_encode($r,JSON_PRETTY_PRINT));echo json_encode($r);exit($r['failed']?1:0);
